style.css:
@-moz-document domain("discord.com") {
:root{
    --eco-green: #6dff6d;
    --eco-green-hover: #9cff9c;
}

/* Background */
body,
.appMount-2yBXZl,
.bg-1QIAus,
.wrapper-1_HaEi,
#app-mount {
    background: url("https://i.postimg.cc/zDFcbFDg/download.jpg") center center / cover fixed no-repeat !important;
}

/* Dark transparent overlays */
.theme-dark,
.theme-dark .container-2cd8Mz,
.theme-dark .chat-2ZfjoI,
.theme-dark .sidebar-1tnWFu,
.theme-dark .contentRegion-3HkfJJ,
.theme-dark .contentRegionScroller-2_GT_N,
.theme-dark .members-3WRCEx,
.theme-dark .panels-3wFtMD,
.theme-dark .title-31SJ6t {
    background: rgba(15, 25, 20, 0.45) !important;
    backdrop-filter: blur(10px);
}

/* Green text */
body,
span,
div,
p,
h1,
h2,
h3,
label,
strong {
    color: var(--eco-green) !important;
}

/* Channel names */
[class*="name"] {
    color: var(--eco-green) !important;
}

/* Messages */
[class*="messageContent"] {
    color: #a8ffa8 !important;
}

/* Usernames */
[class*="username"] {
    color: #6dff6d !important;
    font-weight: bold;
}

/* Links */
a {
    color: #7cff7c !important;
}

/* Buttons */
button {
    background: rgba(0, 120, 40, 0.55) !important;
    color: white !important;
    border-radius: 8px;
}

button:hover {
    background: rgba(0, 180, 60, 0.8) !important;
}

/* Inputs */
input,
textarea {
    background: rgba(0,0,0,.35) !important;
    color: var(--eco-green) !important;
    border: 1px solid #59ff59 !important;
}

/* Scrollbars */
::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-thumb {
    background: #38d938;
    border-radius: 10px;
}
}
